import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
)

// listSkipDirs are directory names never worth descending into when scanning
// for projects: VCS metadata, the project record dir itself, dependency
// trees, and build output.
var listSkipDirs = map[string]bool{
	".git":         true,
	".intropy":     true,
	"node_modules": true,
	"bin":          true,
	"dist":         true,
}

// ScaffoldEntry is one project found by ListScaffolds: the directory holding
// the record plus the record itself. The embedded Scaffold flattens into the
// JSON document so each entry is self-describing for machine consumers.
type ScaffoldEntry struct {
	Path string `json:"path"`
	Scaffold
}

// ListScaffolds walks the tree rooted at root and returns an entry for every
// directory that contains .intropy/scaffold.json, in lexical walk order.
// Paths are reported as WalkDir yields them (root-prefixed), so with a
// relative root they stay usable from the caller's working directory. A
// matched directory is not descended into — projects do not nest. Unreadable
// directories and malformed records become warnings rather than failures so
// one bad project cannot hide the rest.
func ListScaffolds(root string) (entries []ScaffoldEntry, warnings []error) {
	walkErr := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			warnings = append(warnings, err)
			return nil
		}
		if !d.IsDir() {
			return nil
		}
		if path != root && listSkipDirs[d.Name()] {
			return fs.SkipDir
		}

		record := filepath.Join(path, filepath.FromSlash(ScaffoldRelPath))
		if _, err := os.Stat(record); err != nil {
			if !os.IsNotExist(err) {
				warnings = append(warnings, fmt.Errorf("stat %s: %w", record, err))
			}
			return nil
		}
		s, err := LoadScaffold(record)
		if err != nil {
			// Still a project root — don't descend looking for more.
			warnings = append(warnings, err)
			return fs.SkipDir
		}
		entries = append(entries, ScaffoldEntry{Path: path, Scaffold: *s})
		return fs.SkipDir
	})
	if walkErr != nil {
		warnings = append(warnings, walkErr)
	}
	return entries, warnings
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"text/tabwriter"

	"github.com/integrio-intropy/intropy-cli/internal/blueprint"
	"github.com/spf13/cobra"
)

type intListFlags struct {
	output string
}

var intListOpts intListFlags

var intListCmd = &cobra.Command{
	Use:   "list [dir]",
	Short: "List scaffolded integrations under a directory",
	Long: "Walk the directory tree from dir (default: the current directory) and list every project carrying a " +
		blueprint.ScaffoldRelPath + " record written by `int create`. " +
		"Matched projects are not descended into, and .git, .intropy, node_modules, bin and dist are skipped. " +
		"Use --output json for a machine-readable document including the pinned source and scaffold values.",
	Args: cobra.MaximumNArgs(1),
	RunE: func(cmd *cobra.Command, args []string) error {
		if err := validateOutputFlag(intListOpts.output, "json", "plain"); err != nil {
			return err
		}
		root := "."
		if len(args) == 1 {
			root = args[0]
		}
		if info, err := os.Stat(root); err != nil {
			return fmt.Errorf("list: %w", err)
		} else if !info.IsDir() {
			return newUsageErrorf("list: %s is not a directory", root)
		}

		entries, warnings := blueprint.ListScaffolds(root)
		for _, w := range warnings {
			fmt.Fprintln(cmd.ErrOrStderr(), "warning:", w)
		}

		if intListOpts.output == "json" {
			if entries == nil {
				entries = []blueprint.ScaffoldEntry{}
			}
			enc := json.NewEncoder(cmd.OutOrStdout())
			enc.SetIndent("", "  ")
			return enc.Encode(entries)
		}

		if len(entries) == 0 {
			fmt.Fprintln(cmd.ErrOrStderr(), "No scaffolded integrations found.")
			return nil
		}

		tw := tabwriter.NewWriter(cmd.OutOrStdout(), 0, 0, 2, ' ', 0)
		fmt.Fprintln(tw, "PATH\tTEMPLATE\tVERSION")
		for _, e := range entries {
			fmt.Fprintf(tw, "%s\t%s\t%s\n", e.Path, e.Template, e.Version)
		}
		return tw.Flush()
	},
}

func init() {
	f := intListCmd.Flags()
	f.StringVarP(&intListOpts.output, "output", "o", "plain", "output format: plain or json")
	intCmd.AddCommand(intListCmd)
}

package blueprint

import (
	"os"
	"path/filepath"
	"testing"
)

// writeProject creates dir with a scaffold.json naming the template after the
// last path segment, so tests can assert which projects were found.
func writeProject(t *testing.T, dir string) {
	t.Helper()
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	s := testScaffold()
	s.Template = filepath.Base(dir)
	if err := WriteScaffold(dir, s); err != nil {
		t.Fatal(err)
	}
}

func entryPaths(entries []ScaffoldEntry) []string {
	paths := make([]string, len(entries))
	for i, e := range entries {
		paths[i] = e.Path
	}
	return paths
}

func TestListScaffoldsFindsNestedProjects(t *testing.T) {
	root := t.TempDir()
	writeProject(t, filepath.Join(root, "alpha"))
	writeProject(t, filepath.Join(root, "team", "beta"))

	entries, warnings := ListScaffolds(root)
	if len(warnings) != 0 {
		t.Fatalf("warnings = %v", warnings)
	}
	want := []string{filepath.Join(root, "alpha"), filepath.Join(root, "team", "beta")}
	if got := entryPaths(entries); len(got) != 2 || got[0] != want[0] || got[1] != want[1] {
		t.Errorf("paths = %v, want %v", got, want)
	}
	if entries[0].Template != "alpha" || entries[1].Template != "beta" {
		t.Errorf("templates = %q, %q", entries[0].Template, entries[1].Template)
	}
}

func TestListScaffoldsSkipsIgnoredDirs(t *testing.T) {
	root := t.TempDir()
	for _, dir := range []string{".git", ".intropy", "node_modules", "bin", "dist"} {
		writeProject(t, filepath.Join(root, dir, "hidden"))
	}
	writeProject(t, filepath.Join(root, "visible"))

	entries, warnings := ListScaffolds(root)
	if len(warnings) != 0 {
		t.Fatalf("warnings = %v", warnings)
	}
	if got := entryPaths(entries); len(got) != 1 || got[0] != filepath.Join(root, "visible") {
		t.Errorf("paths = %v, want only visible", got)
	}
}

func TestListScaffoldsDoesNotDescendIntoMatchedProject(t *testing.T) {
	root := t.TempDir()
	writeProject(t, filepath.Join(root, "outer"))
	writeProject(t, filepath.Join(root, "outer", "inner"))

	entries, warnings := ListScaffolds(root)
	if len(warnings) != 0 {
		t.Fatalf("warnings = %v", warnings)
	}
	if got := entryPaths(entries); len(got) != 1 || got[0] != filepath.Join(root, "outer") {
		t.Errorf("paths = %v, want only outer", got)
	}
}

func TestListScaffoldsMatchesRootItself(t *testing.T) {
	root := t.TempDir()
	writeProject(t, root)
	writeProject(t, filepath.Join(root, "nested"))

	entries, warnings := ListScaffolds(root)
	if len(warnings) != 0 {
		t.Fatalf("warnings = %v", warnings)
	}
	if got := entryPaths(entries); len(got) != 1 || got[0] != root {
		t.Errorf("paths = %v, want only root", got)
	}
}

func TestListScaffoldsWarnsOnMalformedRecord(t *testing.T) {
	root := t.TempDir()
	bad := filepath.Join(root, "broken", ".intropy")
	if err := os.MkdirAll(bad, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(bad, "scaffold.json"), []byte("{not json"), 0o644); err != nil {
		t.Fatal(err)
	}
	writeProject(t, filepath.Join(root, "ok"))

	entries, warnings := ListScaffolds(root)
	if len(warnings) != 1 {
		t.Fatalf("warnings = %v, want exactly one", warnings)
	}
	if got := entryPaths(entries); len(got) != 1 || got[0] != filepath.Join(root, "ok") {
		t.Errorf("paths = %v, want only ok", got)
	}
}

