	if err := rootCmd.Execute(); err != nil {
		t.Fatalf("execute: %v", err)
	}

	var entries []map[string]any
	if err := json.Unmarshal(stdout.Bytes(), &entries); err != nil {
		t.Fatalf("stdout is not JSON: %v\n%s", err, stdout.String())
